// Reject page. Opening the link shows the form (Odoo answers "rejecting" with a summary);
// the button POSTs the comment. The result shown depends on Odoo's answer, never assumed.
const trigger = $('Webhook Short').isExecuted ? $('Webhook Short') : $('Webhook');
const q = trigger.first().json.query || {};
const linkParams = q.c
  ? { code: q.c }
  : { res_model: q.res_model || '', res_id: parseInt(q.res_id || 0), review_id: parseInt(q.review_id || 0),
      user_id: parseInt(q.user_id || 0), token: q.token || '' };
const r = $json.result || {};
const esc = (v) => String(v || '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

return [{ html: `<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Reject request</title>
<style>
  body { margin:0; padding:24px 16px; background:#f4f5f7; color:#212529;
         font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Arial,sans-serif; }
  .card { max-width:420px; margin:24px auto; background:#fff; border:1px solid #dee2e6; border-radius:6px;
          border-top:4px solid #dc3545; padding:20px 22px; }
  .card.muted-top { border-top-color:#adb5bd; }
  .brand { font-size:11px; letter-spacing:.06em; text-transform:uppercase; color:#6c757d; }
  h1 { font-size:19px; margin:6px 0 14px; }
  .ref { font-size:16px; font-weight:600; }
  .muted { color:#6c757d; font-size:13px; margin-top:2px; }
  .details { margin:12px 0 16px; padding:10px 12px; background:#f8f9fa; border-radius:4px; font-size:14px; line-height:1.5; color:#495057; }
  .lbl { display:block; font-size:13px; font-weight:600; margin-bottom:4px; }
  textarea { width:100%; box-sizing:border-box; border:1px solid #dee2e6; border-radius:4px; padding:8px;
             font:inherit; font-size:14px; margin-bottom:6px; }
  .err { color:#dc3545; font-size:13px; min-height:18px; margin-bottom:8px; }
  button { width:100%; padding:12px; border:0; border-radius:4px; background:#dc3545; color:#fff; font-size:15px; font-weight:600; cursor:pointer; }
  button.secondary { background:#6c757d; width:auto; padding:8px 18px; font-size:13px; margin-top:14px; }
  button:disabled { opacity:.6; }
  .result { text-align:center; }
  .big { font-size:44px; margin-bottom:6px; }
  .quote { margin-top:12px; padding:8px 12px; border-left:3px solid #dc3545; background:#f8f9fa; text-align:left;
           font-size:13px; color:#495057; word-break:break-word; }
</style></head>
<body><div class="card" id="card">
  <div class="brand">Kinden Vietnam · E-Approval</div>
  <h1>Reject this request?</h1>
  <div id="summary">
    ${r.ref ? `<div class="ref">${esc(r.ref)}</div>` : ''}
    ${(r.title || r.applicant) ? `<div class="muted">${esc(r.title)}${r.title && r.applicant ? ' · ' : ''}${esc(r.applicant)}</div>` : ''}
    ${r.step ? `<div class="muted">${esc(r.step)}</div>` : ''}
    ${r.details ? `<div class="details">${esc(r.details)}</div>` : '<div style="height:12px"></div>'}
  </div>
  <label for="cmt" class="lbl">Reason <span style="color:#dc3545">(required)</span></label>
  <textarea id="cmt" rows="4" placeholder="Why do you reject this request? The applicant will see it."></textarea>
  <div id="cmterr" class="err"></div>
  <button id="btn" onclick="reject()">Reject</button>
</div>
<script>
const SUMMARY = document.getElementById('summary').innerHTML;
function esc(v) { const d = document.createElement('div'); d.textContent = v == null ? '' : String(v); return d.innerHTML; }
function page(icon, title, text, extra, muted) {
  const card = document.getElementById('card');
  card.className = 'card' + (muted ? ' muted-top' : '');
  card.innerHTML = '<div class="brand">Kinden Vietnam · E-Approval</div>' + SUMMARY +
    '<div class="result"><div class="big">' + icon + '</div><h1>' + esc(title) + '</h1>' +
    '<div class="muted">' + esc(text) + '</div>' + (extra || '') + '</div>';
}
async function reject() {
  const cmt = document.getElementById('cmt');
  const comment = cmt.value.trim();
  if (!comment) { document.getElementById('cmterr').textContent = 'Please write a reason before rejecting.'; cmt.focus(); return; }
  const btn = document.getElementById('btn'); btn.disabled = true; btn.textContent = 'Rejecting…';
  try {
    const res = await fetch('', { method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ jsonrpc:'2.0', params: Object.assign(${JSON.stringify(linkParams)}, { action:'reject', comment: comment }) }) });
    if (!res.ok) throw new Error('The server did not answer (HTTP ' + res.status + ').');
    const raw = await res.json(); const rpc = Array.isArray(raw) ? raw[0] : raw;
    if (rpc.error) throw new Error(rpc.error.message || 'Odoo returned an error.');
    const out = rpc.result || {};
    if (out.status === 'rejected') {
      page('❌', 'Rejected', 'Your rejection was recorded in Odoo and the applicant has been informed.',
           '<div class="quote"><b>Your reason:</b> ' + esc(out.comment || comment) + '</div>');
      setTimeout(function(){ window.close(); }, 4000);
    } else if (out.status === 'already_processed') {
      const what = out.current_status === 'approved' ? 'approved' : out.current_status === 'rejected' ? 'rejected' : 'decided';
      page('ℹ️', 'Already decided', 'This step was already ' + what + (out.done_by ? ' by ' + out.done_by : '') +
           ', so nothing was changed.', '', true);
    } else if (out.status === 'rejecting') {
      btn.disabled = false; btn.textContent = 'Reject';
      document.getElementById('cmterr').textContent = 'Please write a reason before rejecting.';
    } else {
      throw new Error(out.message || 'Unexpected answer from Odoo.');
    }
  } catch (e) {
    page('⚠️', 'Not rejected', e.message,
         '<button class="secondary" onclick="location.reload()">Try again</button>', true);
  }
}
</script></body></html>` }];

