<body><div class="card" id="card">
  <div class="brand">Kinden Vietnam · E-Approval</div>
  <h1>Approve this request?</h1>
  <div class="ref">${esc(r.ref)}</div>
  <div class="muted">${esc(r.title)} · ${esc(r.applicant)}</div>
