  ${r.comment_required ? `<label for="cmt" class="lbl">Comment <span style="color:#dc3545">(required)</span></label>
  <textarea id="cmt" rows="3" placeholder="Why do you approve this request?"></textarea>
  <div id="cmterr" class="err"></div>` : ''}
  <button id="btn" onclick="approve()">Approve</button>
</div>
<script>
async function approve() {
  const cmt = document.getElementById('cmt');
  const comment = cmt ? cmt.value.trim() : '';
  if (cmt && !comment) { document.getElementById('cmterr').textContent = 'Please write a comment before approving.'; cmt.focus(); return; }
  const btn = document.getElementById('btn'); btn.disabled = true; btn.textContent = 'Approving…';
  const card = document.getElementById('card');
  try {
    const res = await fetch('', { method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ jsonrpc:'2.0', params: Object.assign(${JSON.stringify(linkParams)}, { action:'approve', confirmed:true, comment: comment }) }) });
    let raw = await res.json(); const rpc = Array.isArray(raw) ? raw[0] : raw;
    const out = rpc.result || {};
    if (rpc.error || out.status === 'error') throw new Error(rpc.error ? rpc.error.message : (out.message || 'Action blocked.'));
    if (out.status === 'comment_required') { location.reload(); return; }
    const done = out.status === 'approved';
    card.innerHTML = '<div class="result"><div class="big">' + (done ? '✅' : 'ℹ️') + '</div><h1>' +
      (done ? 'Approved' : 'Already reviewed') + '</h1><div class="muted">' +
      (done ? 'Thank you. Your approval was recorded in Odoo.' : 'This step was already approved or rejected.') + '</div></div>';
    if (done) setTimeout(function(){ window.close(); }, 2500);
  } catch (e) {
    card.innerHTML = '<div class="result"><div class="big">⚠️</div><h1>Not approved</h1><div class="muted"></div>' +
      '<button onclick="location.reload()" style="margin-top:14px;background:#6c757d">Try again</button></div>';
    card.querySelector('.muted').textContent = e.message;
  }
}
</script></body></html>` }];

